  Notation HD2 pc mm q pt bits xra x8 x9 a0 a3 a7 x19 x21 t4 t6 :=
    (CL pc mm q xra (Z_to_bv 64 (DST + Q2 - 2)) (Z_to_bv 64 (64 - tl)) x8 x9 a0 (Z_to_bv 64 64) a3 (Z_to_bv 64 (SS + O2 + pt)) a7
        x19 x21 (Z_to_bv 64 bits) (Z_to_bv 64 67064) t4 t6).

  (* [comment removed for export] *)
  Lemma y32_join2 : forall q pt nb bits flag mm (xra x8 x9 a0 x19 x21 t4 t6 : word),
    X4F' mm SPL BD -> 0 <= q <= Q2 -> 0 <= nb <= pt -> nb <= 8 -> pt - nb + 8 <= L2 -> 0 <= bits <= 64 ->
    (flag = 0 \/ flag = 1) ->
    (forall q' pt' bits' mm' (xra' x8' x9' a0' a3' a7' x19' x21' t4' t6' : word),
       X4F' mm' SPL BD -> q < q' <= Q2 -> 0 <= pt' -> (pt' = 0 \/ pt' + 8 <= L2) -> 0 <= bits' <= 64 ->
       evt psegs POST (HD2 0x177f4 mm' q' pt' bits' xra' x8' x9' a0' a3' a7' x19' x21' t4' t6')) ->
    evt psegs POST (HD2 0x17830 mm q pt bits xra x8 x9 a0 (Z_to_bv 64 flag) (Z_to_bv 64 nb) x19 x21 t4 t6).
Proof using All.
